const formatDate = (dateString) => {
  if (!dateString) return "ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â";
  try {
    return new Date(dateString).toLocaleDateString("en-PK", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  } catch {
    return dateString;
  }
};

const formatDateTime = (dateString) => {
  if (!dateString) return "ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â";
  try {
    return new Date(dateString).toLocaleString("en-PK", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return dateString;
  }
};

const formatTime = (timeString) => {
  if (!timeString) return "ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â";
  try {
    return new Date(`2000-01-01T${timeString}`).toLocaleTimeString("en-PK", {
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return timeString;
  }
};

const getStatusBadge = (status, statusMap) => {
  const info = statusMap?.[status] || { label: status || "Unknown", color: "bg-gray-50 text-gray-700 border-gray-200" };
  return <Badge className={`${info.color} text-[10px] sm:text-xs`}>{info.label}</Badge>;
};

