const RouteModal = ({ isOpen, onClose, mode, formData, setFormData, onSave, loading }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-full max-w-[95%] sm:max-w-lg bg-white rounded-xl sm:rounded-2xl shadow-2xl max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between px-4 sm:px-6 py-3 sm:py-4 border-b border-gray-100 sticky top-0 bg-white rounded-t-xl sm:rounded-t-2xl">
          <h3 className="font-semibold text-gray-800 text-base sm:text-lg flex items-center gap-2">
            <MapPin className="w-4 h-4 sm:w-5 sm:h-5 text-blue-600" />
            {mode === "add" ? "Add Route" : "Edit Route"}
          </h3>
          <button onClick={onClose} className="p-1.5 sm:p-2 rounded-lg hover:bg-gray-100 text-gray-400 transition-colors">
            <X className="w-4 h-4 sm:w-5 sm:h-5" />
          </button>
        </div>

        <div className="p-4 sm:p-6 space-y-3 sm:space-y-4">
          <div>
            <label className="block text-xs sm:text-sm font-medium text-gray-600 mb-1">Route Name <span className="text-red-500">*</span></label>
            <input
              type="text"
              placeholder="e.g., Route B"
              value={formData.name || ""}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="w-full px-3 sm:px-4 py-1.5 sm:py-2.5 border border-gray-200 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm sm:text-base"
            />
          </div>
          <div>
            <label className="block text-xs sm:text-sm font-medium text-gray-600 mb-1">Description</label>
            <textarea
              rows={2}
              placeholder="Route description..."
              value={formData.description || ""}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="w-full px-3 sm:px-4 py-1.5 sm:py-2.5 border border-gray-200 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm sm:text-base resize-none"
            />
          </div>
          <div>
            <label className="block text-xs sm:text-sm font-medium text-gray-600 mb-1">Start Point</label>
            <input
              type="text"
              placeholder="e.g., Township"
              value={formData.start_point || ""}
              onChange={(e) => setFormData({ ...formData, start_point: e.target.value })}
              className="w-full px-3 sm:px-4 py-1.5 sm:py-2.5 border border-gray-200 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm sm:text-base"
            />
          </div>
          <div>
            <label className="block text-xs sm:text-sm font-medium text-gray-600 mb-1">End Point</label>
            <input
              type="text"
              placeholder="e.g., School"
              value={formData.end_point || ""}
              onChange={(e) => setFormData({ ...formData, end_point: e.target.value })}
              className="w-full px-3 sm:px-4 py-1.5 sm:py-2.5 border border-gray-200 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm sm:text-base"
            />
          </div>
        </div>

        <div className="px-4 sm:px-6 py-3 sm:py-4 border-t border-gray-100 flex flex-col-reverse sm:flex-row justify-end gap-2 sm:gap-3 bg-gray-50/50 rounded-b-xl sm:rounded-b-2xl">
          <Button onClick={onClose} disabled={loading} variant="outline" size="sm" className="w-full sm:w-auto min-h-[36px] sm:min-h-[40px]">Cancel</Button>
          <Button onClick={onSave} disabled={loading || !formData.name} variant="primary" size="sm" className="w-full sm:w-auto min-h-[36px] sm:min-h-[40px]">
            {loading ? <RefreshCw className="w-3.5 h-3.5 sm:w-4 sm:h-4 mr-1.5 sm:mr-2 animate-spin" /> : <CheckCircle className="w-3.5 h-3.5 sm:w-4 sm:h-4 mr-1.5 sm:mr-2" />}
            {mode === "add" ? "Add Route" : "Save Changes"}
          </Button>
        </div>
      </div>
    </div>
  );
};

