  const fetchTransportData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [busesRes, routesRes, busStopsRes, busStudentsRes, attendanceRes, studentsRes] = await Promise.all([
        api.get(BUSES_API),
        api.get(ROUTES_API),
        api.get(BUS_STOPS_API),
        api.get(BUS_STUDENTS_API),
        api.get(TRANSPORT_ATTENDANCE_API),
        api.get(STUDENTS_API),
      ]);

      setBuses(busesRes.data?.results || busesRes.data || []);
      setRoutes(routesRes.data?.results || routesRes.data || []);
      setBusStops(busStopsRes.data?.results || busStopsRes.data || []);
      setBusStudents(busStudentsRes.data?.results || busStudentsRes.data || []);
      setAttendance(attendanceRes.data?.results || attendanceRes.data || []);
      setStudents(studentsRes.data?.results || studentsRes.data || []);
    } catch (error) {
      console.error("Failed to fetch transport data:", error);
      if (error.response?.status === 401) {
        setError("Authentication failed. Please login again.");
      } else if (error.response?.status === 404) {
        setError("Transport endpoint not found.");
      } else {
        setError(error.response?.data?.detail || "Failed to load transport data");
      }
      setBuses([]);
      setRoutes([]);
      setBusStops([]);
      setBusStudents([]);
      setAttendance([]);
      setStudents([]);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchTransportData();
  }, [fetchTransportData]);

